VFT-01.code:
@layer components {
  .profile-card {
    border: var(--shelf-border-width) solid var(--shelf-color-border);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-spacing-md);
  }

  .profile-card-title {
    font-size: var(--shelf-font-size-lg);
    font-weight: var(--shelf-font-weight-bold);
    color: var(--shelf-color-text-primary);
    line-height: var(--shelf-line-height-tight);
  }

  .profile-card-subtitle {
    font-size: var(--shelf-font-size-sm);
    color: var(--shelf-color-text-secondary);
    line-height: var(--shelf-line-height-normal);
  }

  .profile-card-skeleton-bar {
    height: var(--shelf-size-skeleton-height);
    background-color: var(--shelf-color-skeleton-base);
    border-radius: var(--shelf-radius-sm);
    animation: shimmer var(--shelf-duration-slow) var(--shelf-easing-linear) infinite;
  }

  .profile-card-skeleton-bar--full {
    width: var(--shelf-size-full);
  }

  .profile-card-skeleton-bar--short {
    width: var(--shelf-size-skeleton-short);
  }

  @keyframes shimmer {
    from {
      opacity: var(--shelf-opacity-skeleton-from);
    }
    to {
      opacity: var(--shelf-opacity-skeleton-to);
    }
  }
}

