VFT-C1.code:
@layer components {
  .status-badge {
    display: inline-flex;
    align-items: center;
    border-radius: var(--shelf-radius-full);
    padding-block: var(--shelf-space-xs);
    padding-inline: var(--shelf-space-sm);
    font-size: var(--shelf-font-size-xs);
    font-weight: var(--shelf-font-weight-medium);
    background-color: var(--shelf-bgColor-subtle);
    color: var(--shelf-fgColor-muted);
  }

  .status-badge--reading {
    background-color: var(--shelf-bgColor-accent);
    color: var(--shelf-fgColor-on-accent);
  }

  .status-badge--finished {
    background-color: var(--shelf-bgColor-accent);
    color: var(--shelf-fgColor-on-accent);
  }

  .status-badge--want-to-read {
    background-color: var(--shelf-bgColor-subtle);
    color: var(--shelf-fgColor-default);
  }

  .status-badge--unread {
    background-color: var(--shelf-bgColor-subtle);
    color: var(--shelf-fgColor-muted);
  }
}
